/// <summary>
/// MPJ_17989 - kscerri - 12/14/2021
/// constructor
/// </summary>
/// <returns>constructor</returns>
public static METCustAuditReportController construct()
{
    return new METCustAuditReportController();
}

/// <summary>
/// MPJ_3863 - kscerri - 05/08/2021
/// Main method to run report
/// </summary>
/// <param name = "_args">args</param>
public static void main(Args _args)
{
    SrsReportRunController controller  = METCustAuditReportController::construct();
    controller.parmReportName(ssrsReportStr(METCustAuditReport, Report));
    controller.parmArgs(_args);
    controller.parmDialogCaption("@MET:CustAuditReport");
    controller.startOperation();
}
